-- Paso 2: ejecutar en el portal solo después de verificar el resultado del script de sede.
-- Pausar el robot y las escrituras en ambas bases. Conservar una copia de seguridad.
-- Asigna exclusivamente guid_system. Conserva los IDs, las relaciones y ambos indicadores de sincronización.
USE mirtheda_bahm;
DROP TEMPORARY TABLE IF EXISTS tmp_bahm_guid_cab, tmp_bahm_guid_det;
CREATE TEMPORARY TABLE tmp_bahm_guid_cab (id BIGINT UNSIGNED PRIMARY KEY, guid VARCHAR(45) NOT NULL UNIQUE, huella CHAR(32) NOT NULL);
CREATE TEMPORARY TABLE tmp_bahm_guid_det (id BIGINT UNSIGNED PRIMARY KEY, guid VARCHAR(45) NOT NULL UNIQUE, huella CHAR(32) NOT NULL, id_padre BIGINT UNSIGNED NOT NULL, guid_padre VARCHAR(45) NOT NULL);
-- Aborta las escrituras si un identificador, una huella o un GUID cambió desde la revisión.
SELECT COUNT(*) INTO @bahm_cab_validas FROM tmp_bahm_guid_cab m
JOIN tb_servicios_sistemas t ON t.id = m.id AND CONVERT(MD5(CONCAT_WS('|',COALESCE(HEX(CAST(t.`clues` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`folio` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`fchregistro` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`ccveusuario` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`descripcion` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`servicios_activo_fijo_id` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`departamentos_activo_fijo_id` AS BINARY)), '-'))) USING ascii) = m.huella
LEFT JOIN tb_servicios_sistemas ocupada ON ocupada.guid_system = m.guid
WHERE (t.guid_system IS NULL OR TRIM(t.guid_system) = '' OR t.guid_system = m.guid) AND (ocupada.id IS NULL OR ocupada.id = t.id);
SELECT COUNT(*) INTO @bahm_det_validos FROM tmp_bahm_guid_det m
JOIN tb_servicios_sistemas_detalle t ON t.id = m.id AND CONVERT(MD5(CONCAT_WS('|',COALESCE(HEX(CAST(t.`fchregistro` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`ccveusuario` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`ccvematerial` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`serie_id` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`seguimiento` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`servicio_id` AS BINARY)), '-'))) USING ascii) = m.huella
JOIN tb_servicios_sistemas p ON p.id = m.id_padre
LEFT JOIN tmp_bahm_guid_cab mc ON mc.id = p.id AND mc.guid = m.guid_padre
LEFT JOIN tb_servicios_sistemas_detalle ocupada ON ocupada.guid_system = m.guid
WHERE (t.guid_system IS NULL OR TRIM(t.guid_system) = '' OR t.guid_system = m.guid) AND (ocupada.id IS NULL OR ocupada.id = t.id) AND (p.guid_system = m.guid_padre OR
      (mc.id IS NOT NULL AND (p.guid_system IS NULL OR TRIM(p.guid_system) = '')));
SET @bahm_ok = (@bahm_cab_validas = 977 AND @bahm_det_validos = 781);
SELECT @bahm_ok AS listo_para_escribir, @bahm_cab_validas AS cabeceras_validadas, @bahm_det_validos AS detalles_validados;
UPDATE tb_servicios_sistemas t JOIN tmp_bahm_guid_cab m ON m.id = t.id AND CONVERT(MD5(CONCAT_WS('|',COALESCE(HEX(CAST(t.`clues` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`folio` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`fchregistro` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`ccveusuario` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`descripcion` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`servicios_activo_fijo_id` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`departamentos_activo_fijo_id` AS BINARY)), '-'))) USING ascii) = m.huella
SET t.guid_system = m.guid WHERE @bahm_ok = 1 AND (t.guid_system IS NULL OR TRIM(t.guid_system) = '');
SELECT ROW_COUNT() AS cabeceras_actualizadas;
SELECT COUNT(*) INTO @bahm_cab_confirmadas FROM tmp_bahm_guid_cab m JOIN tb_servicios_sistemas t ON t.id=m.id AND t.guid_system=m.guid AND CONVERT(MD5(CONCAT_WS('|',COALESCE(HEX(CAST(t.`clues` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`folio` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`fchregistro` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`ccveusuario` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`descripcion` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`servicios_activo_fijo_id` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`departamentos_activo_fijo_id` AS BINARY)), '-'))) USING ascii)=m.huella;
UPDATE tb_servicios_sistemas_detalle t JOIN tmp_bahm_guid_det m ON m.id = t.id AND CONVERT(MD5(CONCAT_WS('|',COALESCE(HEX(CAST(t.`fchregistro` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`ccveusuario` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`ccvematerial` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`serie_id` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`seguimiento` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`servicio_id` AS BINARY)), '-'))) USING ascii) = m.huella
JOIN tb_servicios_sistemas p ON p.id=m.id_padre AND p.guid_system=m.guid_padre
SET t.guid_system = m.guid WHERE @bahm_ok = 1 AND @bahm_cab_confirmadas = 977
  AND (t.guid_system IS NULL OR TRIM(t.guid_system) = '');
SELECT ROW_COUNT() AS detalles_actualizados;
SELECT @bahm_cab_confirmadas AS cabeceras_confirmadas, COUNT(*) AS detalles_confirmados
FROM tmp_bahm_guid_det m JOIN tb_servicios_sistemas_detalle t ON t.id=m.id AND t.guid_system=m.guid AND CONVERT(MD5(CONCAT_WS('|',COALESCE(HEX(CAST(t.`fchregistro` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`ccveusuario` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`ccvematerial` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`serie_id` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`seguimiento` AS BINARY)), '-'),COALESCE(HEX(CAST(t.`servicio_id` AS BINARY)), '-'))) USING ascii)=m.huella
JOIN tb_servicios_sistemas p ON p.id=m.id_padre AND p.guid_system=m.guid_padre;
DROP TEMPORARY TABLE tmp_bahm_guid_cab, tmp_bahm_guid_det;
